import com.financasponto.entity.Usuario; import com.financasponto.repository.UsuarioRepository; import com.financasponto.service.GmailService; import com.google.api.services.gmail.Gmail; import com.google.api.services.gmail.model.ListMessagesResponse; import com.google.api.services.gmail.model.Message; import org.springframework.boot.CommandLineRunner; import org.springframework.stereotype.Component; import java.util.List; @Component public class TestQuery implements CommandLineRunner { private final GmailService gmailService; private final UsuarioRepository usuarioRepository; public TestQuery(GmailService gs, UsuarioRepository ur) { this.gmailService = gs; this.usuarioRepository = ur; } @Override public void run(String... args) throws Exception { Usuario user = usuarioRepository.findById(1L).orElseThrow(); Gmail service = gmailService.getGmailService("user-1"); String query = "from:eventos@pmovel.com.br"; System.out.println("TEST QUERY: " + query); ListMessagesResponse response = service.users().messages().list("me").setQ(query).execute(); List<Message> messages = response.getMessages(); System.out.println("FOUND MESSAGES: " + (messages != null ? messages.size() : 0)); } }
